	public static AnimationDefinition of(VulcanAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case WALK -> WALK;
			case STRIKE -> STRIKE;
			case HAMMERFALL -> HAMMERFALL;
			case POUR -> POUR;
			case THROW -> THROW;
			case SUMMON -> SUMMON;
			case STAGGER -> STAGGER;
			case PHASE -> PHASE;
			case INTRO -> INTRO;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in VulcanAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(VulcanAnim.values()).map(VulcanAnimations::of).toList();
	}
